#!/bin/bash
# =============================================================
# VIM Stitch AI Image Downloader
# Downloads all 27 AI-generated images from the Kinetic Noir
# Stitch design export into the stitch-images/ folder.
#
# Usage: bash stitch-images/download-stitch-images.sh
# Run from the repo root directory.
# =============================================================

OUT="stitch-images"
mkdir -p "$OUT"

download() {
  local name="$1"
  local url="$2"
  echo "Downloading $name..."
  curl -sL -o "$OUT/$name" "$url" && echo "  ✓ $name" || echo "  ✗ FAILED: $name"
}

